import {strict as assert} from 'node:assert';
import {readFileSync,writeFileSync} from 'node:fs';
import ts from 'typescript';
import {sourceHash} from '../scripts/quality-inventory';
const base='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const paths=['src/infrastructure/database/schema.ts','src/application/services/export-service.ts','src/infrastructure/database/event-log.ts','src/infrastructure/security/secret-audit-service.ts'];
function audit(path:string,source:string){const tree=ts.createSourceFile(path,source,ts.ScriptTarget.Latest,true);const prepares:any[]=[],violations:any[]=[];
 function visit(node:ts.Node){if(ts.isCallExpression(node)&&ts.isPropertyAccessExpression(node.expression)&&['prepare','query'].includes(node.expression.name.text)){
  const kind=node.expression.name.text,position=tree.getLineAndCharacterOfPosition(node.getStart(tree));let p:ts.Node|undefined=node.parent;
  while(p&&!ts.isStatement(p)&&!ts.isVariableDeclarationList(p))p=p.parent;
  const owned=kind==='prepare'&&!!p&&ts.isVariableDeclarationList(p)&&Boolean(p.flags&ts.NodeFlags.Using);
  const row={kind,line:position.line+1,owned};prepares.push(row);if(!owned)violations.push(row);
 }ts.forEachChild(node,visit);}visit(tree);return{path,sourceHash:sourceHash(source),prepares,violations};}
const inspected=paths.map(path=>audit(path,readFileSync(path,'utf8')));
assert.deepEqual(inspected.map(row=>row.prepares.length),[3,20,2,4]);for(const row of inspected)assert.deepEqual(row.violations,[]);
const negative=paths.map(path=>{const source=readFileSync(path,'utf8'),changed=source.replace(/using (\w+) =/, 'const $1 =');assert.notEqual(changed,source);const result=audit(path,changed);assert.equal(result.violations.length,1);return{path,detected:result.violations};});
const proofs=['schema','export','event','secret'].map(name=>{const path=base+'evidence/B11.74.5-'+name+'.json',record=read(path);let bindings=0;
 for(const input of [...record.sourceInputs,...record.otherInputs,...record.checks[0].sourceInputs,...record.native.sourceInputs]){assert.equal(input.sourceHash,sourceHash(readFileSync(input.path,'utf8')),path+' stale '+input.path);bindings++;}
 assert(record.checks[0].exit===0);for(const run of record.native.runs)assert.equal(run.exit,0);
 return{path,evidenceHash:sourceHash(readFileSync(path,'utf8')),bindings,status:record.status};});
assert(!readFileSync('src/infrastructure/database/connection.ts','utf8').includes('OwnedDatabase'));
const result={item_id:'B11.74.5',status:'local mapped statement migration verified; full quality and factory acceptance remain open',recordedAt:new Date().toISOString(),cwd:process.cwd(),startingRevision:'998d8a8da8d0d76cdfe70eb1d6a75f452cabd44b',sourceInputs:inspected.map(({path,sourceHash})=>({path,sourceHash})),inspection:inspected,negativeAudit:negative,proofs,command:'bun .git/b11-other-audit.ts',exit:0,source:readFileSync('.git/b11-other-audit.ts','utf8'),limits:['Static ownership checks alone are not native acceptance; the four linked native slices establish only their scoped behaviors.','29 current prepares (3schema,20export,2event,4secret); no cached queries in these modules. Historical map had17prepares and10cached export queries. Two added prepares support migration and optional-table checks.','All four slices have paired Windows runtime proof. No full Linux/platform, counter completeness, package/changed-line, installed/CLI or independent acceptance.','Required Q004/Q019/Q100/Q101 and B11.74.7 remain open; Q100 retains a failing whole-replay preservation probe. Factory is unchanged.']};
writeFileSync(base+'evidence/B11.74.5.json',JSON.stringify(result,null,2)+'\n');
console.log(JSON.stringify({prepares:inspected.map(row=>({path:row.path,count:row.prepares.length})),negative:negative.length,proofBindings:proofs.map(p=>p.bindings)}));
